import{_ as t,o as r,c as l,a2 as a}from"./chunks/framework.BG8d4IEm.js";const d=JSON.parse('{"title":"技术写作须知","description":"","frontmatter":{"tags":["翻译","方法论"]},"headers":[],"relativePath":"posts/2020-01-18-notes-on-technical-writing.md","filePath":"posts/2020-01-18-notes-on-technical-writing.md"}'),o={name:"posts/2020-01-18-notes-on-technical-writing.md"};function i(n,e,s,c,p,h){return r(),l("div",null,[...e[0]||(e[0]=[a('<h1 id="技术写作须知" tabindex="-1">技术写作须知 <a class="header-anchor" href="#技术写作须知" aria-label="Permalink to &quot;技术写作须知&quot;">​</a></h1><blockquote><p>该译文对应原文: <a href="https://mkaz.blog/misc/notes-on-technical-writing/" target="_blank" rel="noreferrer">Notes on Technical Writing</a></p></blockquote><p>再过去的一年,我断断续续为 WordPress 文档工作。在冻结发布期间,我开始为开发者迁移到新平台做出贡献。我发现自己很享受写文档,同时写文档也有益于帮助和指导他人。虽然这不是我的主要工作,我还是会抽出时间保持贡献。</p><p>这段时间,我阅读了大量关于技术写作的资料。这是我的笔记,不仅帮助我后续记忆,也可作为我目前写作的参考工具。</p><h2 id="原则" tabindex="-1">原则 <a class="header-anchor" href="#原则" aria-label="Permalink to &quot;原则&quot;">​</a></h2><p>以下原则是撰写文档时须谨记的</p><ul><li>技术写作的目的是更快更好的帮助用户完成任务</li><li>实践出真知,演示优于描述</li><li>让用户尽快获得成功 <blockquote><p>译者注: 技术写作必须尽早让用户获得反馈和价值</p></blockquote></li><li>文档类型不是只有一种 <blockquote><p>译者注: 要根据目的选择技术文档的类型</p></blockquote></li></ul><h2 id="建议" tabindex="-1">建议 <a class="header-anchor" href="#建议" aria-label="Permalink to &quot;建议&quot;">​</a></h2><ul><li>明确你的受众和写作意图</li><li>重要的信息放在前面</li><li>善用列表 <blockquote><p>译者注:例如编写技术教程,采用有序列表编排示例步骤,便于读者操作和定位问题。</p></blockquote></li><li>一个段落,一个概念</li><li>勤于修改</li></ul><h2 id="避免元写作" tabindex="-1">避免元写作 <a class="header-anchor" href="#避免元写作" aria-label="Permalink to &quot;避免元写作&quot;">​</a></h2><p>避免写描述写作的内容,文字本身没有思想,是笔者和读者赋予了文字灵魂。</p><p>你不需要告知读者接下来要说什么,直接说就好了。</p><ul><li><strong>反例:</strong> 本章节讨论影响名气起伏的因素</li><li><strong>范例:</strong> 名气起伏受什么影响?</li></ul><p>不要在写作中引用章节</p><ul><li><strong>反例:</strong> 总结上一章关于......</li><li><strong>范例:</strong> 综上所述.....</li></ul><p>不要描述极度复杂的概念,同样也不要讲显而易见的内容。读者会自行判断概念的难易。</p><h2 id="极简教学" tabindex="-1">极简教学 <a class="header-anchor" href="#极简教学" aria-label="Permalink to &quot;极简教学&quot;">​</a></h2><p>John M. Carroll 和他在 IBM 的同事研究如何创建支持文档,分析使用户熟练掌握的最佳方案。在 1980 年代，他们开发了一种极简方法，并编写了一本极佳的<a href="https://www.utwente.nl/en/bms/ist/minimalism/displaywriter.pdf" target="_blank" rel="noreferrer">《IBM Displaywriter 操作员培训手册》</a>，提供给首次使用文本处理器的人。</p><blockquote><p>译者注: <a href="http://www.obsoletecomputermuseum.org/displayw/" target="_blank" rel="noreferrer">Displaywriter</a> 是 IBM 开发的电子文档编辑器</p></blockquote><p>极简教学的四条原则:</p><ul><li>选择面向行动的方法,用户总期望做点什么。这条原则反映了极简主义以用户为中心的本质。</li><li>明确任务域的工具。工具是达到目的的手段。该原则要求设计人员选择对用户有意义的培训任务。</li><li>提供错误识别和恢复,人非圣贤,孰能无过,提升用户处理错误的体验和能力。</li><li>明确准备,学习,定位。设计必须尽可能满足目标受众的不同需求和倾向。该原则也反映了极简主义的以用户为中心的本质。</li></ul><p><a href="https://www.utwente.nl/en/bms/ist/minimalism/" target="_blank" rel="noreferrer">深入阅读极简教学</a>出自荷兰特文特大学的教学技术系。</p><h2 id="建构主义" tabindex="-1">建构主义 <a class="header-anchor" href="#建构主义" aria-label="Permalink to &quot;建构主义&quot;">​</a></h2><p>美国心理学家 Jerome Bruner 研究人类认知心理学。布鲁纳著作的一个主要议题是确认学习是一个主动的过程，学习者基于已有的知识构建新的概念。将建构主义原理应用于文档：</p><ul><li>鼓励读者去发现原理</li><li>将信息转换为读者当前可以接受的水平</li><li>以递进方式编排材料,在已掌握知识上构筑新的概念</li><li>融入活动对话框,鼓励用户去操作 “试一下”,&quot;看看发生了什么&quot;,&quot;自行验证&quot;</li></ul><p>进一步阅读 <a href="https://www.instructionaldesign.org/theories/constructivist/" target="_blank" rel="noreferrer">Bruner 构建理论</a></p><h2 id="文档类型" tabindex="-1">文档类型 <a class="header-anchor" href="#文档类型" aria-label="Permalink to &quot;文档类型&quot;">​</a></h2><p>Daniele Procida 撰写了<a href="https://www.divio.com/blog/documentation/" target="_blank" rel="noreferrer">关于文档你不知道的</a> 不是所有的东西都叫文档，这里(至少) 有四种类型文档。</p><ol><li><strong>教程(Tutorials)</strong> 教程面向教学针对初学者,通过一系列指导课程,给用户提供基本的信心和技能。教程不应该预设知识或语言,但是任可帮助那些一无所知的初学者。</li><li><strong>使用指南</strong> 使用指南或者 FAQ 是面向目标的。由用户确定,使用指南可以假定用户具有预设知识和语言，但是需要知道如何解决特定问题。</li><li><strong>说明</strong> 说明或概述文档是面向理解的，提供背景或额外详细的上下文 <blockquote><p>译者注: 这类似文档概念建立和术语阐述章节,例如 <a href="https://webpack.js.org/concepts/" target="_blank" rel="noreferrer">webpack concept</a></p></blockquote></li><li><strong>参考指南</strong> 参考指南是面向信息的，它应该准确而完整的描述机理。API 文档是参考指南的典型事例。</li></ol><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="https://developers.google.com/tech-writing/one" target="_blank" rel="noreferrer">Google Technical Writing</a></li></ul>',31)])])}const b=t(o,[["render",i]]);export{d as __pageData,b as default};
